using System.Text.Json.Nodes;
using System.Diagnostics;
using Sales360.Domain;
namespace Sales360.Api;
public static class Documents
{
    public static void Map(RouteGroupBuilder api,Store store,string data,Func<HttpContext,string> company,Func<HttpContext,string> actor,Action<HttpContext,string[]> role,string root)
    {
        api.MapGet("/contracts",async(HttpContext h)=>{await using var c=await store.Open();return await Store.Rows(c,"SELECT * FROM contract WHERE company_id=@p0 ORDER BY uploaded_at DESC",company(h));});
        api.MapPost("/contracts",async(HttpContext h)=>{role(h,["Accountant","Finance Administrator"]);var form=await h.Request.ReadFormAsync();var file=form.Files.GetFile("file")??throw new RuleException("Select a PDF contract.");Billing.Require(file.Length>5&&file.Length<=20*1024*1024,"Contract must be within 20 MB.");using var ms=new MemoryStream();await file.CopyToAsync(ms);var bytes=ms.ToArray();Billing.Require(System.Text.Encoding.ASCII.GetString(bytes,0,5)=="%PDF-","This increment accepts PDF contracts only; actual PDF signature required.");var hash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(bytes));var folder=Path.Combine(data,"documents",company(h));Directory.CreateDirectory(folder);var path=Path.Combine(folder,hash+".pdf");await File.WriteAllBytesAsync(path,bytes);
            return await store.Transaction(company(h),async c=>{var id=Guid.NewGuid().ToString("N");await Store.Exec(c,"INSERT INTO contract(id,company_id,name,hash,size,mime,uploaded_by) VALUES(@p0,@p1,@p2,@p3,@p4,'application/pdf',@p5) ON CONFLICT(company_id,hash) DO NOTHING",id,company(h),Path.GetFileName(file.FileName),hash,file.Length,actor(h));var record=await Store.One(c,"SELECT * FROM contract WHERE company_id=@p0 AND hash=@p1",company(h),hash);await Store.Audit(c,company(h),actor(h),"Contract quarantined",record.Text("id"),new{hash});return record;});
        }).DisableAntiforgery();
        api.MapPost("/contracts/{id}/scan",async(HttpContext h,string id)=>{role(h,["System Administrator"]);await using var c=await store.Open();var x=await Store.One(c,"SELECT * FROM contract WHERE company_id=@p0 AND id=@p1",company(h),id);var scanner=Environment.GetEnvironmentVariable("SALES360_MALWARE_SCANNER");Billing.Require(!string.IsNullOrWhiteSpace(scanner)&&File.Exists(scanner),"Configure SALES360_MALWARE_SCANNER to the absolute clamscan executable. File remains quarantined.");var psi=new ProcessStartInfo(scanner!){UseShellExecute=false,CreateNoWindow=true};psi.ArgumentList.Add("--no-summary");psi.ArgumentList.Add(Path.Combine(data,"documents",company(h),x.Text("hash")+".pdf"));using var p=Process.Start(psi)!;using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(45));await p.WaitForExitAsync(timeout.Token);Billing.Require(p.ExitCode==0,"Malware scan did not return clean. File remains quarantined.");await store.Transaction(company(h),async cx=>{await Store.Exec(cx,"UPDATE contract SET status='Accepted - extraction review required' WHERE id=@p0",id);await Store.Audit(cx,company(h),actor(h),"Malware scan clean",id,new{scanner=Path.GetFileName(scanner)});return 0;});return new{id,status="Accepted - extraction review required"};});
        api.MapPost("/contracts/{id}/decision",async(HttpContext h,string id,JsonObject b)=>{role(h,["Accountant","Finance Administrator"]);return await store.Transaction(company(h),async c=>{var x=await Store.One(c,"SELECT * FROM contract WHERE company_id=@p0 AND id=@p1",company(h),id);Billing.Require(x.Text("status").StartsWith("Accepted"),"Contract must pass malware scanning before acceptance.");Billing.Require(new[]{"Yes","No","Later"}.Contains(b.Text("decision")),"Choose Yes, No or Later.");Billing.Require(x.Text("decision")=="","Project decision already recorded. Reopen the linked project or pending task.");if(b.Text("decision")=="Yes")await Store.One(c,"SELECT id FROM project WHERE company_id=@p0 AND id=@p1",company(h),b.Text("project_id"));await Store.Exec(c,"UPDATE contract SET decision=@p0,project_id=nullif(@p1,'') WHERE id=@p2",b.Text("decision"),b.Text("project_id"),id);await Store.Audit(c,company(h),actor(h),"Contract project decision",id,b);return new{id,decision=b.Text("decision")};});});
        api.MapGet("/certificates/{id}/pdf",async(HttpContext h,string id)=>{await using var c=await store.Open();var x=await Store.One(c,"SELECT x.*,p.name AS project,p.code AS job,p.category,c.name AS customer,c.terms FROM certificate x JOIN project p ON p.id=x.project_id JOIN customer c ON c.id=x.customer_id WHERE x.company_id=@p0 AND x.id=@p1",company(h),id);var prev=await Store.Rows(c,"SELECT reference,claim_date,settlement FROM certificate WHERE company_id=@p0 AND project_id=@p1 AND state='Approved' AND id<>@p2 AND cumulative<=@p3 ORDER BY claim_date,reference",company(h),x.Text("project_id"),id,x.Decimal("previous"));x["previous_certificates"]=prev;x["words"]=Billing.Words(x.Decimal("settlement"));var result=await Generate(root,data,"certificate",x);await store.Transaction(company(h),async cx=>{await Store.Audit(cx,company(h),actor(h),"Certificate PDF downloaded",id,new{snapshot=x.Text("snapshot_hash")});return 0;});return Results.File(result,"application/pdf",x.Text("reference").Replace('/','-')+".pdf");});
        api.MapGet("/statements/pdf",async(HttpContext h,string customerId,string asOf)=>{await using var c=await store.Open();var customer=await Store.One(c,"SELECT * FROM customer WHERE company_id=@p0 AND id=@p1",company(h),customerId);var statement=System.Text.Json.JsonSerializer.SerializeToNode(await Reports.Statement(c,company(h),customerId,asOf))!.AsObject();statement["customer"]=customer.Text("name");return Results.File(await Generate(root,data,"statement",statement),"application/pdf","Statement-"+asOf+".pdf");});
    }
    public static async Task<byte[]> Generate(string root,string data,string kind,JsonObject payload)
    {
        var python=Environment.GetEnvironmentVariable("SALES360_PYTHON");Billing.Require(!string.IsNullOrWhiteSpace(python)&&File.Exists(python),"PDF engine unavailable. Configure SALES360_PYTHON with ReportLab installed.");var folder=Path.Combine(data,"generated");Directory.CreateDirectory(folder);var token=Guid.NewGuid().ToString("N");var input=Path.Combine(folder,token+".json");var output=Path.Combine(folder,token+".pdf");await File.WriteAllTextAsync(input,payload.ToJsonString());try {var psi=new ProcessStartInfo(python!){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true};psi.ArgumentList.Add(Path.Combine(root,"scripts","render_pdf.py"));psi.ArgumentList.Add(kind);psi.ArgumentList.Add(input);psi.ArgumentList.Add(output);using var p=Process.Start(psi)!;var error=p.StandardError.ReadToEndAsync();using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(45));await p.WaitForExitAsync(timeout.Token);if(p.ExitCode!=0)Console.Error.WriteLine("PDF renderer diagnostic: "+await error);Billing.Require(p.ExitCode==0,"PDF rendering failed. Check configured fonts and ReportLab runtime.");return await File.ReadAllBytesAsync(output);}finally{File.Delete(input);File.Delete(output);}
    }
}
